package com.novalang.bukkit.types.inventory;
import com.novalang.bukkit.Requires; import com.novalang.bukkit.types.value.NovaTypeSupport; import com.novalang.runtime.host.JavaTypes; import org.bukkit.inventory.AnvilInventory;
@Requires(classes = {"org.bukkit.inventory.AnvilInventory"}) public final class NovaAnvilInventory { private NovaAnvilInventory() { } public static void register(JavaTypes.Builder b) { b.extension(AnvilInventory.class,"renameText",f->f.returns(String.class).invoke(a->NovaTypeSupport.argument(a,0,AnvilInventory.class).getRenameText())); b.extension(AnvilInventory.class,"repairCost",f->f.returns(Integer.class).invoke(a->NovaTypeSupport.argument(a,0,AnvilInventory.class).getRepairCost())); b.extension(AnvilInventory.class,"setRepairCost",f->f.param("cost",Integer.class).returns(Void.TYPE).invoke(a->{NovaTypeSupport.argument(a,0,AnvilInventory.class).setRepairCost(NovaTypeSupport.argument(a,1,Integer.class));return null;})); } }
